// Format Gemini Result — parses Gemini generateContent response

const items = $input.all();
const prepItems = $('Prepare Gemini Request').all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const prep = prepItems[i]?.json || {};
  const response = items[i].json;
  const fileName = prep.original_file_name || 'unknown';

  if (response.error) {
    throw new Error('Gemini API error for "' + fileName + '": ' + (response.error.message || JSON.stringify(response.error)) + '. Document was NOT ingested.');
  }

  const candidate = response.candidates?.[0];
  const finishReason = candidate?.finishReason || 'unknown';

  if (!candidate) {
    throw new Error('Gemini returned no candidates for "' + fileName + '". Document was NOT ingested.');
  }

  if (finishReason !== 'STOP' && finishReason !== 'MAX_TOKENS') {
    throw new Error('Gemini extraction ended with finishReason=' + finishReason + ' for "' + fileName + '". Document was NOT ingested.');
  }

  let text = '';
  const parts = candidate.content?.parts || [];
  for (const part of parts) { if (part.text) text += part.text; }
  text = text.trim();

  if (!text) {
    throw new Error('Gemini returned empty text for "' + fileName + '" despite finishReason=' + finishReason + '. Document was NOT ingested.');
  }

  const inputTokens = response.usageMetadata?.promptTokenCount || 0;
  const outputTokens = response.usageMetadata?.candidatesTokenCount || 0;

  if (inputTokens > 1000 && outputTokens < inputTokens * 0.1) {
    throw new Error('Gemini extraction suspiciously short for "' + fileName + '": ' + outputTokens + ' output tokens for ' + inputTokens + ' input tokens (' + (outputTokens / inputTokens * 100).toFixed(1) + '%). The model likely truncated. Document was NOT ingested.');
  }

  out.push({
    json: {
      text: text,
      method: 'gemini_flash',
      file_id: prep.file_id || '',
      original_file_name: fileName,
      last_modified: prep.last_modified || null,
      folder: prep.folder || '',
      folder_path: prep.folder_path || ''
    }
  });
}

return out;

